/**
 * Pinterest API for Conversions Adapter
 *
 * Adapts standardized event payloads into Pinterest Conversions API format.
 * Handles both browser pixel and server-to-server (S2S) data structures.
 *
 * @see https://developers.pinterest.com/docs/conversions/best/
 * @see https://developers.pinterest.com/docs/api/v5/#operation/events/create
 * @see https://developers.pinterest.com/docs/conversions/event/
 */

(function (wpm, $) {
	"use strict";

	/**
	 * Pinterest Event Adapter
	 */
	class PinterestAdapter {
		/**
		 * Adapt event data to Pinterest format
		 *
		 * @param {object} eventData - Standardized event data
		 * @param {string} eventName - Event name (e.g., "add_to_cart")
		 * @param {object} context - Additional context (user, page, etc.)
		 * @returns {object|null} Pinterest-formatted event data or null if event not supported
		 */
		adapt(eventData, eventName, context) {
			// Only process if Pinterest pixel is loaded
			if (!wpmDataLayer?.pixels?.pinterest?.loaded) {
				return null;
			}

			// Map event names to adaptation methods
			const eventMap = {
				add_to_cart   : () => this.adaptAddToCart(eventData),
				view_item     : () => this.adaptPageVisit(eventData),
				begin_checkout: () => this.adaptCheckout(eventData),
				purchase      : () => this.adaptPurchase(eventData),
				search        : () => this.adaptSearch(eventData),
				view_category : () => this.adaptPageVisit(eventData),
				signup        : () => this.adaptSignup(eventData),
				lead          : () => this.adaptLead(eventData),
			};

			if (eventMap[eventName]) {
				return eventMap[eventName]();
			}

			return null;
		}

		/**
		 * Get base Pinterest event data structure
		 *
		 * @returns {object} Base event data with event_id, user, and page
		 */
		getBaseData() {
			return wpm.getPinterestS2SBaseData();
		}

		/**
		 * Adapt AddToCart event
		 *
		 * @param {object} eventData - Event data with product information
		 * @returns {object} Pinterest addtocart event
		 */
		adaptAddToCart(eventData) {
			const data      = this.getBaseData();
			data.event_name = "addtocart";

			if (eventData.product) {
				data.custom_data = wpm.pinterestGetProductDataForCapiEvent(eventData.product);
			}

			return data;
		}

		/**
		 * Adapt PageVisit event (product or category view)
		 *
		 * @param {object} eventData - Event data with product information
		 * @returns {object} Pinterest pagevisit event
		 */
		adaptPageVisit(eventData) {
			const data      = this.getBaseData();
			data.event_name = "pagevisit";

			if (eventData.product) {
				data.custom_data = wpm.pinterestGetProductDataForCapiEvent(eventData.product);
			}

			return data;
		}

		/**
		 * Adapt Checkout event
		 *
		 * @param {object} eventData - Event data with cart items
		 * @returns {object} Pinterest checkout event
		 */
		adaptCheckout(eventData) {
			const data      = this.getBaseData();
			data.event_name = "checkout";

			if (eventData.items && eventData.items.length > 0) {
				data.custom_data = {
					value      : eventData.value || 0,
					currency   : eventData.currency || wpmDataLayer.shop.currency,
					content_ids: eventData.items.map(item => wpm.getProductIdForSpecificPixel(item, "pinterest")),
					num_items  : eventData.items.reduce((total, item) => total + item.quantity, 0),
				};
			}

			return data;
		}

		/**
		 * Adapt Purchase event
		 *
		 * @param {object} eventData - Event data with transaction information
		 * @returns {object} Pinterest checkout event (Pinterest uses checkout for completed purchases)
		 */
		adaptPurchase(eventData) {
			const data = this.getBaseData();
			// Use order ID for purchase event to match server-side event ID
			if (wpmDataLayer?.order?.id) {
				data.event_id = wpmDataLayer.order.id.toString();
			}
			data.event_name = "checkout";

			if (eventData.transaction) {
				const transaction = eventData.transaction;
				data.custom_data  = {
					value   : transaction.value || 0,
					currency: transaction.currency || wpmDataLayer.shop.currency,
					order_id: transaction.transaction_id || transaction.order_id,
				};

				if (transaction.items && transaction.items.length > 0) {
					data.custom_data.content_ids = transaction.items.map(item => wpm.getProductIdForSpecificPixel(item, "pinterest"));
					data.custom_data.num_items   = transaction.items.reduce((total, item) => total + item.quantity, 0);
				}
			}

			return data;
		}

		/**
		 * Adapt Search event
		 *
		 * @param {object} eventData - Event data with search query
		 * @returns {object} Pinterest search event
		 */
		adaptSearch(eventData) {
			const data      = this.getBaseData();
			data.event_name = "search";

			data.custom_data = {
				search_query: wpm.getSearchTermFromUrl(),
			};

			return data;
		}

		/**
		 * Adapt Signup event
		 *
		 * @param {object} eventData - Event data with user information
		 * @returns {object} Pinterest signup event
		 */
		adaptSignup(eventData) {
			const data      = this.getBaseData();
			data.event_name = "signup";

			return data;
		}

		/**
		 * Adapt Lead event
		 *
		 * @param {object} eventData - Event data with lead information
		 * @returns {object} Pinterest lead event
		 */
		adaptLead(eventData) {
			const data      = this.getBaseData();
			data.event_name = "lead";

			if (eventData.value) {
				data.custom_data = {
					value   : eventData.value,
					currency: eventData.currency || wpmDataLayer.shop.currency,
				};
			}

			return data;
		}
	}

	// Register the adapter with S2S capabilities
	const adapter = new PinterestAdapter();
	wpm.registerAdapter("pinterest", adapter, {
		supportsS2S               : true,
		supportsEventDeduplication: true,
		isActive                  : () => wpmDataLayer?.pixels?.pinterest?.loaded === true,
	});

})(window.wpm = window.wpm || {}, jQuery);
